local BattlementMaker = {}
local PRODUCTS = {
    simple_stone_battlement = { name = "Preprost kamnit cinasti venec", stoneCost = 4, time = 5, cost = 200, defense = 25, happiness = 1, description = "Preprost kamnit cinasti venec za obzidje." },
    marble_crenellation = { name = "Marmornata cinaston", marbleCost = 3, stoneCost = 1, time = 8, cost = 480, defense = 38, happiness = 2, prestige = 3, description = "Marmornata cinaston za trgovce." },
    silver_inlaid_battlement = { name = "Srebrnovloženi cinasti venec", marbleCost = 3, silverCost = 1, stoneCost = 1, time = 12, cost = 1100, defense = 52, happiness = 2, prestige = 8, description = "Srebrnovloženi cinasti venec za plemiče." },
    gold_trimmed_battlement = { name = "Zlatookrasni cinasti venec", marbleCost = 3, goldCost = 1, silverCost = 1, stoneCost = 1, time = 16, cost = 2500, defense = 65, happiness = 3, prestige = 18, description = "Zlatookrasni cinasti venec za visoke plemiče." },
    jewel_set_battlement = { name = "Draguljasta cinasti venec", marbleCost = 3, goldCost = 2, silverCost = 1, stoneCost = 1, jewelCost = 1, time = 20, cost = 5200, defense = 78, happiness = 5, prestige = 32, description = "Cinasti venec z draguljem za visoko plemstvo." },
    royal_grand_battlement = { name = "Kraljevski veliki cinasti venec", marbleCost = 4, goldCost = 3, silverCost = 2, stoneCost = 1, jewelCost = 2, pearlCost = 2, time = 27, cost = 11000, defense = 92, happiness = 13, prestige = 65, description = "Veliki kraljevski cinasti venec z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    battlement_workshop = { name = "Cinasna delavnica", cost = { gold = 320, wood = 100, stone = 200, marble = 4 }, upkeep = 7, qualityBonus = 5 },
    mason_loft = { name = "Zidarska podstrešje", cost = { gold = 1100, wood = 240, stone = 320, silver = 6, marble = 6 }, upkeep = 26, qualityBonus = 18 },
    master_mason_atelier = { name = "Mojstrski zidarski atelje", cost = { gold = 2900, wood = 360, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_mason_palace = { name = "Kraljevska zidarska palača", cost = { gold = 12500, wood = 580, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
BattlementMaker.stoneStock = 18; BattlementMaker.marbleStock = 12; BattlementMaker.silverStock = 6; BattlementMaker.goldStock = 6; BattlementMaker.jewelStock = 4; BattlementMaker.pearlStock = 4
BattlementMaker.productStock = {}; BattlementMaker.buildings = {}; BattlementMaker.maker = nil; BattlementMaker.activeMaking = {}; BattlementMaker.totalProducts = 0; BattlementMaker.dayTimer = 0
function BattlementMaker.init() BattlementMaker.stoneStock=18; BattlementMaker.marbleStock=12; BattlementMaker.silverStock=6; BattlementMaker.goldStock=6; BattlementMaker.jewelStock=4; BattlementMaker.pearlStock=4; BattlementMaker.productStock={}; BattlementMaker.buildings={}; BattlementMaker.maker=nil; BattlementMaker.activeMaking={}; BattlementMaker.totalProducts=0; BattlementMaker.dayTimer=0; print("[BattlementMaker] Royal Battlement Maker System initialized (6 products, 4 buildings)") end
function BattlementMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BattlementMaker.maker={name=n or ("Cinasar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Cinasar najet: %s (spretnost: %d)",BattlementMaker.maker.name,s),"success") end; return true end
function BattlementMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BattlementMaker.build(id) local ok,e=BattlementMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BattlementMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BattlementMaker.getQualityBonus() local b=0; for _,bd in ipairs(BattlementMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BattlementMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.stoneCost and BattlementMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.marbleCost and BattlementMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.silverCost and BattlementMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BattlementMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BattlementMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BattlementMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BattlementMaker.buildings==0 then return false,"Potrebna cinasna delavnica" end; if not BattlementMaker.maker then return false,"Potreben cinasar" end; return true end
function BattlementMaker.make(pt,qty) qty=qty or 1; local ok,e=BattlementMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.stoneCost then BattlementMaker.stoneStock=BattlementMaker.stoneStock-d.stoneCost*qty end; if d.marbleCost then BattlementMaker.marbleStock=BattlementMaker.marbleStock-d.marbleCost*qty end; if d.silverCost then BattlementMaker.silverStock=BattlementMaker.silverStock-d.silverCost*qty end; if d.goldCost then BattlementMaker.goldStock=BattlementMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BattlementMaker.jewelStock=BattlementMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BattlementMaker.pearlStock=BattlementMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BattlementMaker.maker then t=math.max(1,t-math.floor(BattlementMaker.maker.skill/12)) end; table.insert(BattlementMaker.activeMaking,{id="battlement_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klesanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BattlementMaker.completeMaking(m) local q=1.0+(BattlementMaker.getQualityBonus()/100); if BattlementMaker.maker then q=q+(BattlementMaker.maker.skill/140) end; q=math.min(2.5,q); BattlementMaker.productStock[m.productType]=(BattlementMaker.productStock[m.productType] or 0)+m.quantity; BattlementMaker.totalProducts=BattlementMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BattlementMaker.maker then BattlementMaker.maker.itemsMade=BattlementMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BattlementMaker.maker.skill=math.min(100,BattlementMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Cinasti venec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"battlement.completed",{productName=m.productName,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function BattlementMaker.update(dt) if not _G.state then return end; BattlementMaker.dayTimer=BattlementMaker.dayTimer+dt; if BattlementMaker.dayTimer>=30 then BattlementMaker.dayTimer=0; for i=#BattlementMaker.activeMaking,1,-1 do local m=BattlementMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BattlementMaker.completeMaking(m); table.remove(BattlementMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BattlementMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BattlementMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BattlementMaker.getStats() return {stoneStock=BattlementMaker.stoneStock,marbleStock=BattlementMaker.marbleStock,silverStock=BattlementMaker.silverStock,goldStock=BattlementMaker.goldStock,jewelStock=BattlementMaker.jewelStock,pearlStock=BattlementMaker.pearlStock,productStock=BattlementMaker.productStock,numBuildings=#BattlementMaker.buildings,hasMaker=BattlementMaker.maker~=nil,makerName=BattlementMaker.maker and BattlementMaker.maker.name or "—",makerSkill=BattlementMaker.maker and BattlementMaker.maker.skill or 0,activeMaking=#BattlementMaker.activeMaking,totalProducts=BattlementMaker.totalProducts} end
return BattlementMaker
